update companies c set
  listening_platform        = s.platform,
  listening_platforms_all   = s.platforms_all,
  listening_evidence_date   = s.evidence_date,
  listening_glint_last_seen = s.glint_last,
  listening_source          = 'sumble',
  listening_checked_at      = now()
from src s
where (s.dom <> '' and lower(regexp_replace(regexp_replace(regexp_replace(coalesce(c.website,''),'^https?://',''),'^www\.',''),'/.*$','')) = s.dom)
   or lower(btrim(c.name)) = lower(btrim(s.nm));

